function pageBudgetDefaults(pageId?: string): PreviewPageBudget { const index = pages.findIndex((page) => page.id === pageId); return { usdBdtRate: 120, monthlyBdt: index === 0 ? 500 : index === 1 ? 300 : null, dailyBdt: null, hardLimit: index < 2, warningThreshold: 85, pausedByBudget: false, reservedBdt: 0 }; }
