export function getPreviewBudgetSummary(pageId: string) { const page = pageFor(pageId); const budget = getPreviewPageBudget(page.id); const usage = getPreviewUsage(page.id).month; const usedBdt = usage.estimatedCostBdt; return { ...budget, usedBdt, remainingBdt: budget.monthlyBdt === null ? null : Math.max(0, budget.monthlyBdt - usedBdt), state: budget.pausedByBudget ? "PAUSED_BY_BUDGET" : budget.monthlyBdt !== null && usedBdt >= budget.monthlyBdt ? "LIMIT_REACHED" : budget.monthlyBdt !== null && usedBdt >= budget.monthlyBdt * budget.warningThreshold / 100 ? "WARNING" : "HEALTHY", calls: usage.calls, inputTokens: usage.inputTokens, cachedInputTokens: 0, outputTokens: usage.outputTokens, estimatedUsd: usage.estimatedCost, costBdt: usedBdt }; }
export function updatePreviewPageBudget(pageId: string, input: Partial<PreviewPageBudget>) { const key = pageKey(pageId); const next = { ...getPreviewPageBudget(key), ...input }; previewState.pageBudgets.set(key, next); if (next.monthlyBdt !== null && getPreviewBudgetSummary(key).usedBdt >= next.monthlyBdt && next.hardLimit) { next.pausedByBudget = true; setPreviewAi(false, key); pages = pages.map((item) => item.id === key ? { ...item, aiStatus: "PAUSED_BY_BUDGET" } as PreviewPage : item); createPreviewIssue({ pageId: key, type: "PAGE_BUDGET_LIMIT", title: `${pageFor(key).name} AI is paused by budget`, description: "The Page monthly AI budget has been reached. Incoming messages continue to be stored.", severity: "high", resolutionAction: "Increase the Page budget or resume AI." }); } persistPreviewState(); return getPreviewBudgetSummary(key); }
export function forcePreviewPageBudgetLimit(pageId: string) { const key = pageKey(pageId); const budget = getPreviewPageBudget(key); const usedBdt = getPreviewUsage(key).month.estimatedCostBdt; const next = { ...budget, monthlyBdt: Math.max(0.01, Math.min(budget.monthlyBdt ?? 999999, usedBdt || 0.01)), hardLimit: true, pausedByBudget: true }; previewState.pageBudgets.set(key, next); setPreviewAi(false, key); pages = pages.map((item) => item.id === key ? { ...item, aiStatus: "PAUSED_BY_BUDGET" } as PreviewPage : item); createPreviewIssue({ pageId: key, type: "PAGE_BUDGET_LIMIT", title: `${pageFor(key).name} AI is paused by budget`, description: "Preview simulation reached the Page hard limit.", severity: "high", resolutionAction: "Increase the Page budget or resume AI." }); persistPreviewState(); return getPreviewBudgetSummary(key); }
