export function recordPreviewUsage(pageId: string, inputTokens: number, outputTokens: number, estimatedCost: number, estimatedCostBdt = estimatedCost * getPreviewPageBudget(pageId).usdBdtRate, metadata?: { callType?: PreviewUsageAttempt["callType"]; model?: PreviewUsageAttempt["model"]; cachedInputTokens?: number; status?: PreviewUsageAttempt["status"] }) { const key = pageKey(pageId); const current = previewUsage.get(key) ?? { calls: 0, inputTokens: 0, outputTokens: 0, totalTokens: 0, estimatedCost: 0, estimatedCostBdt: 0 }; previewUsage.set(key, { calls: current.calls + 1, inputTokens: current.inputTokens + inputTokens, outputTokens: current.outputTokens + outputTokens, totalTokens: current.totalTokens + inputTokens + outputTokens, estimatedCost: current.estimatedCost + estimatedCost, estimatedCostBdt: current.estimatedCostBdt + estimatedCostBdt }); const attempts = previewState.usageAttempts.get(key) ?? []; attempts.push({ id: randomUUID(), pageId: key, callType: metadata?.callType ?? "PRELIVE_TEST", model: metadata?.model ?? "deepseek-v4-flash", inputTokens, cachedInputTokens: metadata?.cachedInputTokens ?? 0, outputTokens, estimatedCostUsd: estimatedCost, estimatedCostBdt, fxRate: getPreviewPageBudget(key).usdBdtRate, status: metadata?.status ?? "SUCCEEDED", createdAt: new Date() }); previewState.usageAttempts.set(key, attempts); persistPreviewState(); }
export function getPreviewUsage(pageId?: string) { const page = pageId ? getPreviewPage(pageId) : null; const seed = seeds.find((item) => item.id === page?.id); const base = seed?.usage ?? { today: [0, 0, 0, 0, 0] as [number, number, number, number, number], month: [0, 0, 0, 0, 0] as [number, number, number, number, number], daily: [] as Array<[string, number, number, number, number]> }; const [todayCalls, todayInput, todayOutput, todayTotal, todayCost] = base.today; const [monthCalls, monthInput, monthOutput, monthTotal, monthCost] = base.month; const key = page?.id ?? pageId ?? PAGE_IDS[0]; const extra = previewUsage.get(key); const attempts = previewState.usageAttempts.get(key) ?? []; const cachedInputTokens = attempts.reduce((sum, attempt) => sum + attempt.cachedInputTokens, 0); const today = { calls: todayCalls + (extra?.calls ?? 0), inputTokens: todayInput + (extra?.inputTokens ?? 0), cachedInputTokens, outputTokens: todayOutput + (extra?.outputTokens ?? 0), totalTokens: todayTotal + (extra?.totalTokens ?? 0), estimatedCost: todayCost + (extra?.estimatedCost ?? 0), estimatedCostUsd: todayCost + (extra?.estimatedCost ?? 0), estimatedCostBdt: todayCost * 120 + (extra?.estimatedCostBdt ?? 0) }; const month = { calls: monthCalls + (extra?.calls ?? 0), inputTokens: monthInput + (extra?.inputTokens ?? 0), cachedInputTokens, outputTokens: monthOutput + (extra?.outputTokens ?? 0), totalTokens: monthTotal + (extra?.totalTokens ?? 0), estimatedCost: monthCost + (extra?.estimatedCost ?? 0), estimatedCostUsd: monthCost + (extra?.estimatedCost ?? 0), estimatedCostBdt: monthCost * 120 + (extra?.estimatedCostBdt ?? 0) }; const daily = [...base.daily.map(([date, calls, inputTokens, outputTokens, estimatedCost]) => ({ date, calls, inputTokens, cachedInputTokens: 0, outputTokens, totalTokens: inputTokens + outputTokens, estimatedCost, estimatedCostUsd: estimatedCost, estimatedCostBdt: estimatedCost * 120 })), ...attempts.map((attempt) => ({ date: attempt.createdAt.toISOString().slice(0, 10), calls: 1, inputTokens: attempt.inputTokens, cachedInputTokens: attempt.cachedInputTokens, outputTokens: attempt.outputTokens, totalTokens: attempt.inputTokens + attempt.outputTokens, estimatedCost: attempt.estimatedCostUsd, estimatedCostUsd: attempt.estimatedCostUsd, estimatedCostBdt: attempt.estimatedCostBdt }))]; return { today, month, daily }; }

function previewMemoryKey(pageId: string, customerId: string) { const page = getPreviewPage(pageId); const seed = page && seeds.find((item) => item.id === page.id); if (!page || !seed || seed.customer.id !== customerId || previewState.deletedCustomers.has(customerId)) throw new Error("Customer does not belong to page"); return `${page.id}:${customerId}`; }
function newPreviewMemory(pageId: string, customerId: string): PreviewCustomerMemory { return { pageId, customerId, memory: { knownFacts: { name: seeds.find((item) => item.id === pageId)?.customer.name ?? "" }, unconfirmedFacts: {}, needs: ["delivery timing"], preferences: { preferred_product_type: "everyday care" }, semanticQuestionsAsked: ["name"], recommendedProductIds: [], rejectedProductIds: [], activeOrderReference: `${pageId.slice(0, 8)}-session-01`, summary: "Preview customer memory is ready for inspection." }, facts: [{ id: `${customerId}-name-v1`, pageId, customerId, factKey: "name", normalizedValue: seeds.find((item) => item.id === pageId)?.customer.name ?? "", displayValue: seeds.find((item) => item.id === pageId)?.customer.name ?? "", sourceType: "CUSTOMER_CONFIRMED", status: "ACTIVE", lastConfirmedAt: now, updatedAt: now }], summaryStale: false, summaryVersion: 1 }; }
