export function getPreviewCustomerMemory(pageId: string, customerId: string) { const memory = previewMemory(pageId, customerId); return structuredClone(memory); }
function updatePreviewMemory(pageId: string, customerId: string, fn: (memory: PreviewCustomerMemory) => void) { const memory = previewMemory(pageId, customerId); fn(memory); memory.summaryStale = true; memory.facts = memory.facts.map((fact) => ({ ...fact })); previewState.customerMemory.set(`${pageId}:${customerId}`, memory); persistPreviewState(); return structuredClone(memory); }
export function editPreviewCustomerFact(input: { pageId: string; customerId: string; factKey: string; value: string }) { if (!input.value.trim()) throw new Error("A fact value is required"); return updatePreviewMemory(input.pageId, input.customerId, (memory) => { const current = memory.facts.find((fact) => fact.factKey === input.factKey && fact.status === "ACTIVE"); if (current) { current.status = "SUPERSEDED"; current.supersededByFactId = `${input.customerId}-${input.factKey}-${Date.now()}`; } const id = `${input.customerId}-${input.factKey}-${Date.now()}`; memory.facts.unshift({ id, pageId: input.pageId, customerId: input.customerId, factKey: input.factKey, normalizedValue: input.value.trim(), displayValue: input.value.trim(), sourceType: "ADMIN_CORRECTION", status: "ACTIVE", lastConfirmedAt: new Date(), updatedAt: new Date() }); memory.memory.knownFacts[input.factKey] = input.value.trim(); delete memory.memory.unconfirmedFacts[input.factKey]; }); }
