export function removePreviewCustomerFact(input: { pageId: string; customerId: string; factKey: string }) { return markPreviewCustomerFactUnknown(input); }
export function clearPreviewNonOrderMemory(input: { pageId: string; customerId: string }) { return updatePreviewMemory(input.pageId, input.customerId, (memory) => { for (const fact of memory.facts.filter((item) => item.factKey !== "active_order_session_id" && ["ACTIVE", "UNCONFIRMED"].includes(item.status))) fact.status = "REJECTED"; const activeOrderReference = memory.memory.activeOrderReference; memory.memory = { knownFacts: {}, unconfirmedFacts: {}, needs: [], preferences: {}, semanticQuestionsAsked: [], recommendedProductIds: [], rejectedProductIds: [], activeOrderReference, summary: "" }; }); }
